digraph kr0ki {
  rankdir=LR;
  input [label="IAC / code"];
  diagram [label="procedural diagram"];
  kroki [label="Kroki"];
  artifact [label="SVG / PNG"];
  input -> diagram -> kroki -> artifact;
}

# kr0ki Box-5 Rust code-flow — executable playb00k view source.
direction: right
client: HTTP caller { shape: person }
router: Axum router { shape: hexagon }
service: RenderService { shape: rectangle; style.fill: "#d8eaff" }
cache: FsCache { shape: cylinder; style.fill: "#e9f7df" }
backend: HttpKrokiBackend { shape: rectangle; style.fill: "#fff0cc" }
kroki: Kroki renderer { shape: cloud }
artifact: SVG or PNG { shape: document; style.fill: "#f7e6ff" }
client -> router: POST /render/:format
router -> service: route + auth
service -> cache: lookup
cache -> service: hit or miss
service -> backend: miss only
backend -> kroki: render
kroki -> backend: bytes
backend -> service: artifact
service -> cache: atomic write
service -> client: headers + bytes
client -> artifact: receives

Table cache_entry {
  key varchar [pk]
  bytes blob
}

\begin{document}
\begin{tikzpicture}
  \node[draw, rounded corners] (client) at (0,0) {client};
  \node[draw, rounded corners] (service) at (3,0) {service};
  \node[draw, rounded corners] (cache) at (6,0) {cache};
  \node[draw, rounded corners] (backend) at (9,0) {backend};
  \draw[->] (client) -- (service);
  \draw[->] (service) -- (cache);
  \draw[->] (service) -- (backend);
\end{tikzpicture}
\end{document}

workspace {
    model {
        user = person "Operator"
        kr0ki = softwareSystem "kr0ki" {
            renderer = container "RenderService"
            cache = container "FsCache"
        }
        kroki = softwareSystem "Kroki"
        user -> kr0ki "Submits diagram source"
        kr0ki -> kroki "Renders via"
        renderer -> cache "Reads/writes"
    }
    views {
        systemContext kr0ki {
            include *
            autoLayout
        }
        container kr0ki {
            include *
            autoLayout
        }
    }
}

entity render_service is
  Port ( source         : in  STD_LOGIC;
         format_select  : in  STD_LOGIC;
         request_output : in  STD_LOGIC;
         artifact       : out STD_LOGIC;
         cache_hit      : out STD_LOGIC);
end render_service;
